def find_triplet_product(arr, target):
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if arr[i] * arr[j] * arr[k] == target:
                    return (arr[i], arr[j], arr[k])
    return None

