import java.util.Arrays;

public class QuickSort<T extends Comparable<T>> {
    private int comparisons;

    public void sort(T[] array) {
        comparisons = 0;
        quickSort(array, 0, array.length - 1);
        System.out.println("Total comparisons made: " + comparisons);
    }

    private void quickSort(T[] array, int low, int high) {
        if (low < high) {
            int pivotIndex = partition(array, low, high);
            quickSort(array, low, pivotIndex - 1);
            quickSort(array, pivotIndex + 1, high);
        }
    }

    private int partition(T[] array, int low, int high) {
        T pivot = array[high];
        int i = low - 1;

        for (int j = low; j < high; j++) {
            comparisons++;
            if (array[j].compareTo(pivot) <= 0) {
                i++;
                T temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
        T temp = array[i + 1];
        array[i + 1] = array[high];
        array[high] = temp;
        return i + 1;
    }

    public static void main(String[] args) {
        QuickSort<Integer> sorter = new QuickSort<>();
        Integer[] intArray = {5, 3, 8, 3, 2, 10, 9};
        sorter.sort(intArray);
        System.out.println("Sorted Integers: " + Arrays.toString(intArray));

        QuickSort<String> stringSorter = new QuickSort<>();
        String[] strArray = {"banana", "apple", "orange", "apple"};
        stringSorter.sort(strArray);
        System.out.println("Sorted Strings: " + Arrays.toString(strArray));
    }
}

// Unit tests
import static org.junit.Assert.assertArrayEquals;
import org.junit.Test;

public class QuickSortTest {

    @Test
    public void testSortIntegers() {
        QuickSort<Integer> sorter = new QuickSort<>();
        Integer[] input = {3, 1, 4, 1, 5, 9, 2, 6, 5};
        Integer[] expected = {1, 1, 2, 3, 4, 5, 5, 6, 9};
        sorter.sort(input);
        assertArrayEquals(expected, input);
    }

    @Test
    public void testSortStrings() {
        QuickSort<String> sorter = new QuickSort<>();
        String[] input = {"apple", "banana", "cherry", "apple"};
        String[] expected = {"apple", "apple", "banana", "cherry"};
        sorter.sort(input);
        assertArrayEquals(expected, input);
    }

